SELECT su_nationkey AS supp_nation, SUBSTRING(c_state, 1, 1) AS cust_nation, EXTRACT(YEAR FROM o_entry_d) AS l_year, SUM(ol_amount) AS revenue FROM tpcch.supplier, tpcch.stock, tpcch.orderline, order_view, tpcch.customer, tpcch.nation AS n1, tpcch.nation AS n2 WHERE ol_supply_w_id = s_w_id AND ol_i_id = s_i_id AND s_su_suppkey = su_suppkey AND ol_w_id = o_w_id AND ol_d_id = o_d_id AND ol_o_id = o_id AND c_id = o_c_id AND c_w_id = o_w_id AND c_d_id = o_d_id AND su_nationkey = n1.n_nationkey AND c_n_nationkey = n2.n_nationkey AND ((n1.n_name = 'GERMANY' AND n2.n_name = 'CAMBODIA') OR (n1.n_name = 'CAMBODIA' AND n2.n_name = 'GERMANY')) AND ol_delivery_d BETWEEN '2007-01-02 00:00:00.000000' AND '2012-01-02 00:00:00.000000' GROUP BY su_nationkey, SUBSTRING(c_state, 1, 1), EXTRACT(YEAR FROM o_entry_d) ORDER BY su_nationkey, cust_nation, l_year;
